/**
 * Validate the request before anything touches the database.
 *
 * The batch id is interpolated into the SQL statements, so it is checked
 * against the UUID format here.  A value that is not a UUID never reaches
 * the database.  The shared secret is verified by n8n itself, through the
 * header authentication of the webhook node.
 */

const items = $input.all();
const payload = (items[0] && items[0].json) || {};
const body = payload.body && typeof payload.body === 'object' ? payload.body : payload;

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const batchId = String(body.batch_id || body.batchId || '').trim().toLowerCase();
if (!UUID.test(batchId)) {
  throw new Error('invalid_batch_id: the request must carry a batch id in UUID format');
}

return [{ json: { batch_id: batchId, requested_at: new Date().toISOString() } }];
